"use strict";
window.LC_CHUNKS=window.LC_CHUNKS||{};window.LC_CHUNKS["university_physics_de"]=window.LC_CHUNKS["university_physics_de"]||{};window.LC_CHUNKS["university_physics_de"][36]={"university_physics_de:M36-L1":"<article class=\"lesson-standard\"><h1 id=\"L1\">M36-L1 – Standardmodell, Eichgruppen und elektrische Ladung<\/h1>\n<p><strong>Kursbereich:<\/strong> M36 – Master: Teilchenphysik, Kollisionsexperimente und Beschleuniger<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M30: Quantenfeldtheorie; M34:\nQuantenzustände.<\/p>\n<p><strong>Lernziel:<\/strong> Die Ladungszuordnung eines links-chiralen\nLeptonendubletts in einer festgelegten Hyperladungsnormierung\nberechnen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Das Standardmodell ordnet Materiefelder und ihre Wechselwirkungen\neiner Eichstruktur zu. Die starke Wechselwirkung gehört zu SU(3), die\nelektroschwache Beschreibung zu SU(2) × U(1). Die elektroschwache\nSymmetriebrechung führt zu massiven W- und Z-Bosonen sowie einem\nmasselosen Photon; die Higgs-Kopplungen sind für Fermionmassen relevant.\nEine Eichgruppe ist keine Tabelle konkreter Teilchenmassen.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Wir verwenden die Konvention\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Q<\/mi><mo>=<\/mo><msub><mi>T<\/mi><mn>3<\/mn><\/msub><mo>+<\/mo><mi>Y<\/mi><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">Q=T_3+Y/2<\/annotation><\/semantics><\/math>\nfür die elektrische Ladungszahl in Einheiten von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>e<\/mi><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">e&gt;0<\/annotation><\/semantics><\/math>.\nFür ein linkschirales Leptonendublett\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>ν<\/mi><mi>L<\/mi><\/msub><mo>,<\/mo><msub><mi>e<\/mi><mi>L<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(\\nu_L,e_L)<\/annotation><\/semantics><\/math>\ngilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Y<\/mi><mo>=<\/mo><mi>−<\/mi><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">Y=-1<\/annotation><\/semantics><\/math>,\nwährend die Isospin-Komponente\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>T<\/mi><mn>3<\/mn><\/msub><annotation encoding=\"application/x-tex\">T_3<\/annotation><\/semantics><\/math>\noben\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>+<\/mi><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">+1/2<\/annotation><\/semantics><\/math>\nund unten\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>−<\/mi><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">-1/2<\/annotation><\/semantics><\/math>\nbeträgt. Daraus folgen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Q<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>ν<\/mi><mi>L<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">Q(\\nu_L)=0<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Q<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>e<\/mi><mi>L<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>−<\/mi><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">Q(e_L)=-1<\/annotation><\/semantics><\/math>.\nAndere Bücher definieren\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>Y<\/mi><annotation encoding=\"application/x-tex\">Y<\/annotation><\/semantics><\/math>\nohne Faktor zwei; der physikalische Ladungswert ändert sich nicht.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Q<\/mi><mo>=<\/mo><msub><mi>T<\/mi><mn>3<\/mn><\/msub><mo>+<\/mo><mfrac><mi>Y<\/mi><mn>2<\/mn><\/mfrac><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">Q=T_3+\\frac{Y}{2}.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Für das Dublett\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>ν<\/mi><mi>L<\/mi><\/msub><mo>,<\/mo><msub><mi>e<\/mi><mi>L<\/mi><\/msub><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>T<\/mi><\/msup><\/mrow><annotation encoding=\"application/x-tex\">L=(\\nu_L,e_L)^T<\/annotation><\/semantics><\/math>\nmit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Y<\/mi><mo>=<\/mo><mi>−<\/mi><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">Y=-1<\/annotation><\/semantics><\/math>\nergeben sich die Ladungen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>+<\/mi><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><mo>−<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">+1/2-1/2=0<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>−<\/mi><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><mo>−<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><mo>=<\/mo><mi>−<\/mi><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">-1/2-1/2=-1<\/annotation><\/semantics><\/math>.\nDie eigene Abbildung zeichnet diese beiden Komponenten und die Beiträge\ngetrennt. Es handelt sich um eine Darstellung von Quantenzahlen, nicht\num ein gemessenes Energiespektrum.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_276_DE.svg\"\nalt=\"Zwei Komponenten des linkschiralen Leptonendubletts mit ihren Isospin- und Hyperladungstermen ergeben null und minus eins.\" />\n<figcaption aria-hidden=\"true\">Zwei Komponenten des linkschiralen\nLeptonendubletts mit ihren Isospin- und Hyperladungstermen ergeben null\nund minus eins.<\/figcaption>\n<\/figure>\n<p><em>Schematische Ladungsbilanz im Leptonendublett; festgelegte\nHyperladungsnormierung.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Welches\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>Q<\/mi><annotation encoding=\"application/x-tex\">Q<\/annotation><\/semantics><\/math>\nhat ein linkes Quarkdublett mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Y<\/mi><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">Y=1/3<\/annotation><\/semantics><\/math>\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>T<\/mi><mn>3<\/mn><\/msub><mo>=<\/mo><mi>+<\/mi><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">T_3=+1/2<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Welches\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>Q<\/mi><annotation encoding=\"application/x-tex\">Q<\/annotation><\/semantics><\/math>\nhat das untere Feld desselben Dubletts?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum darf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Y<\/mi><mo>=<\/mo><mi>−<\/mi><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">Y=-1<\/annotation><\/semantics><\/math>\nhier nicht mit der Konvention\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Q<\/mi><mo>=<\/mo><msub><mi>T<\/mi><mn>3<\/mn><\/msub><mo>+<\/mo><mi>Y<\/mi><\/mrow><annotation encoding=\"application/x-tex\">Q=T_3+Y<\/annotation><\/semantics><\/math>\nkombiniert werden?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Q<\/mi><mo>=<\/mo><mi>+<\/mi><mn>2<\/mn><mi>/<\/mi><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">Q=+2/3<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Q<\/mi><mo>=<\/mo><mi>−<\/mi><mn>1<\/mn><mi>/<\/mi><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">Q=-1/3<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Die Normierungen wären gemischt; Quantenzahlen müssen gemeinsam\nkonsistent definiert werden.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Die Rechnung benutzt schwache Isospin-Eigenzustände in einer festen\nKonvention. Sie erklärt weder Flavour-Mischung noch die numerischen\nKopplungskonstanten. Ein rechtshändiges Lepton singlet hat andere\nSU(2)-Quantenzahlen.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Instabile Teilchen bilden einen zentralen Zugang zur experimentellen\nBeschreibung von Prozessen. <a\nhref=\"index.html?course=university_physics&amp;module=M36&amp;lesson=L2&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste Lektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://pdg.lbl.gov/2026/reviews/standard_model_and_related.html\">Particle Data Group – Review of Particle Physics 2026: Standard Model &amp; Related Topics<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachreview-Verzeichnis zu Eichwechselwirkungen, Quarks und Neutrinos; einzelne Gleichungen werden hier eigenständig hergeleitet; Fachlicher Bezug zur Lektion: M36-L1 – Standardmodell, Eichgruppen und elektrische Ladung · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M36-L2":"<article class=\"lesson-standard\"><h1 id=\"L2\">M36-L2 – Instabile Teilchen, Lebensdauer und Zerfallsgesetz<\/h1>\n<p><strong>Kursbereich:<\/strong> M36 – Master: Teilchenphysik, Kollisionsexperimente und Beschleuniger<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M13: statistische Verteilungen;\nM30: Wechselwirkungen.<\/p>\n<p><strong>Lernziel:<\/strong> Eine mittlere Lebensdauer von einer\nHalbwertszeit unterscheiden und eine idealisierte\nÜberlebenswahrscheinlichkeit berechnen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Instabile Teilchen zerfallen zufällig; eine einzelne Lebensdauer ist\nnicht vorhersagbar. In einem Ensemble mit zeitlich konstanter\nZerfallsrate entsteht ein exponentielles Gesetz. Die mittlere\nLebensdauer und die Halbwertszeit sind unterschiedliche Kenngrößen. In\nBeschleunigerexperimenten sind Erzeugung, Flugzeit und Nachweis\nzusätzlich von Bewegung und Detektorselektion abhängig.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Für eine konstante Zerfallsrate\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ<\/mi><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mi>τ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\lambda=1/\\tau<\/annotation><\/semantics><\/math>\nin der Eigenzeit gilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><mi>N<\/mi><mi>/<\/mi><mi>d<\/mi><mi>t<\/mi><mo>=<\/mo><mi>−<\/mi><mi>λ<\/mi><mi>N<\/mi><\/mrow><annotation encoding=\"application/x-tex\">dN/dt=-\\lambda N<\/annotation><\/semantics><\/math>.\nIntegration liefert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msub><mi>N<\/mi><mn>0<\/mn><\/msub><msup><mi>e<\/mi><mrow><mi>−<\/mi><mi>t<\/mi><mi>/<\/mi><mi>τ<\/mi><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">N(t)=N_0e^{-t/\\tau}<\/annotation><\/semantics><\/math>\nund die Überlebenswahrscheinlichkeit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mrow><mi mathvariant=\"normal\">s<\/mi><mi mathvariant=\"normal\">u<\/mi><mi mathvariant=\"normal\">r<\/mi><mi mathvariant=\"normal\">v<\/mi><\/mrow><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msup><mi>e<\/mi><mrow><mi>−<\/mi><mi>t<\/mi><mi>/<\/mi><mi>τ<\/mi><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">P_{\\mathrm{surv}}(t)=e^{-t/\\tau}<\/annotation><\/semantics><\/math>.\nDie Halbwertszeit erfüllt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mrow><mi mathvariant=\"normal\">s<\/mi><mi mathvariant=\"normal\">u<\/mi><mi mathvariant=\"normal\">r<\/mi><mi mathvariant=\"normal\">v<\/mi><\/mrow><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>t<\/mi><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P_{\\mathrm{surv}}(t_{1/2})=1/2<\/annotation><\/semantics><\/math>,\nalso\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>t<\/mi><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><\/msub><mo>=<\/mo><mi>τ<\/mi><mrow><mi mathvariant=\"normal\">ln<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">t_{1/2}=\\tau\\ln2<\/annotation><\/semantics><\/math>.\nFür relativistische Teilchen muss Labordauer von Eigenzeit mittels\nZeitdilatation unterschieden werden.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mrow><mi mathvariant=\"normal\">s<\/mi><mi mathvariant=\"normal\">u<\/mi><mi mathvariant=\"normal\">r<\/mi><mi mathvariant=\"normal\">v<\/mi><\/mrow><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msup><mi>e<\/mi><mrow><mi>−<\/mi><mi>t<\/mi><mi>/<\/mi><mi>τ<\/mi><\/mrow><\/msup><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><msub><mi>t<\/mi><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><\/msub><mo>=<\/mo><mi>τ<\/mi><mrow><mi mathvariant=\"normal\">ln<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">P_{\\mathrm{surv}}(t)=e^{-t/\\tau},\\qquad t_{1/2}=\\tau\\ln 2.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>In einem frei konstruierten Beispiel sei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>τ<\/mi><mo>=<\/mo><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><mi>μ<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\tau=2\\,\\mu\\mathrm{s}<\/annotation><\/semantics><\/math>.\nBei einer verstrichenen Eigenzeit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t<\/mi><mo>=<\/mo><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><mi>μ<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><annotation encoding=\"application/x-tex\">t=2\\,\\mu\\mathrm{s}<\/annotation><\/semantics><\/math>\nverbleiben im Mittel\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>e<\/mi><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><\/msup><mo>≈<\/mo><mn>36<\/mn><mo>,<\/mo><mn>8<\/mn><mi>%<\/mi><\/mrow><annotation encoding=\"application/x-tex\">e^{-1}\\approx36{,}8\\%<\/annotation><\/semantics><\/math>\neines großen Ensembles; die Halbwertszeit beträgt rund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mo>,<\/mo><mn>386<\/mn><mspace width=\"0.167em\"><\/mspace><mi>μ<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><annotation encoding=\"application/x-tex\">1{,}386\\,\\mu\\mathrm{s}<\/annotation><\/semantics><\/math>.\nDie Grafik zeigt das normierte Ensembleverhalten, keine Messung an einem\nbestimmten Teilchen.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_306_DE.svg\"\nalt=\"Exponential abfallende Überlebenskurve mit markierter mittlerer Lebensdauer und Halbwertszeit.\" />\n<figcaption aria-hidden=\"true\">Exponential abfallende Überlebenskurve\nmit markierter mittlerer Lebensdauer und Halbwertszeit.<\/figcaption>\n<\/figure>\n<p><em>Idealisierte Exponentialverteilung eines instabilen\nEnsembles.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Berechne\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>P<\/mi><mrow><mi mathvariant=\"normal\">s<\/mi><mi mathvariant=\"normal\">u<\/mi><mi mathvariant=\"normal\">r<\/mi><mi mathvariant=\"normal\">v<\/mi><\/mrow><\/msub><annotation encoding=\"application/x-tex\">P_{\\mathrm{surv}}<\/annotation><\/semantics><\/math>\nnach\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mi>τ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">2\\tau<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Welche Halbwertszeit gehört zu\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>τ<\/mi><mo>=<\/mo><mn>4<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">n<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\tau=4\\,\\mathrm{ns}<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Gilt die angegebene Form direkt für Laborzeit eines relativistischen\nStrahls?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>e<\/mi><mrow><mi>−<\/mi><mn>2<\/mn><\/mrow><\/msup><mo>≈<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1353<\/mn><\/mrow><annotation encoding=\"application/x-tex\">e^{-2}\\approx0{,}1353<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>4<\/mn><mrow><mi mathvariant=\"normal\">ln<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><mo>≈<\/mo><mn>2<\/mn><mo>,<\/mo><mn>773<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">n<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">4\\ln2\\approx2{,}773\\,\\mathrm{ns}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Nein; zunächst die relativistische Zeitdilatation\nberücksichtigen.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Exponentialverhalten verlangt stationäre Zerfallswahrscheinlichkeit\nund keine relevante Beobachtungsselektion. Die Zahl der Überlebenden ist\nzufällig;\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">N(t)<\/annotation><\/semantics><\/math>\nbeschreibt den Erwartungswert, nicht eine deterministische\nTeilchenliste.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Beim Experiment müssen Zerfallsprodukte aus Spuren und\nEnergieeinträgen rekonstruiert werden. <a\nhref=\"index.html?course=university_physics&amp;module=M36&amp;lesson=L3&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste Lektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://pdg.lbl.gov/2026/reviews/standard_model_and_related.html\">Particle Data Group – Review of Particle Physics 2026: Standard Model &amp; Related Topics<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachreview-Verzeichnis zu Eichwechselwirkungen, Quarks und Neutrinos; einzelne Gleichungen werden hier eigenständig hergeleitet; Fachlicher Bezug zur Lektion: M36-L2 – Instabile Teilchen, Lebensdauer und Zerfallsgesetz · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://pdg.lbl.gov/2026/\">Particle Data Group – Review of Particle Physics 2026<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachliche Übersicht zu Teilchenphysik und Statistik; keine Übernahme fremder Tabellen oder Grafiken; Fachlicher Bezug zur Lektion: M36-L2 – Instabile Teilchen, Lebensdauer und Zerfallsgesetz · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M36-L3":"<article class=\"lesson-standard\"><h1 id=\"L3\">M36-L3 – Streukinematik, Pseudorapidität und Jet-Abstand<\/h1>\n<p><strong>Kursbereich:<\/strong> M36 – Master: Teilchenphysik, Kollisionsexperimente und Beschleuniger<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M30: Streuprozesse; M31: numerische\nRekonstruktion.<\/p>\n<p><strong>Lernziel:<\/strong> Für zwei rekonstruierte Richtungen die\ngeometrische Trennung im Pseudorapidität-Azimut-Raum bestimmen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Kollisionsdetektoren messen Spuren und Energieeinträge, aus denen\nObjekte wie Jets rekonstruiert werden. Für eine Flugrichtung relativ zur\nStrahlachse wird häufig\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>η<\/mi><mo>=<\/mo><mi>−<\/mi><mrow><mi mathvariant=\"normal\">ln<\/mi><mo>&#8289;<\/mo><\/mrow><mrow><mi mathvariant=\"normal\">tan<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>θ<\/mi><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\eta=-\\ln\\tan(\\theta/2)<\/annotation><\/semantics><\/math>\nverwendet. Die Azimutrichtung ist periodisch. Die Größe\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>R<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\Delta R<\/annotation><\/semantics><\/math>\nist ein Abstand im\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>η<\/mi><mo>,<\/mo><mi>ϕ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(\\eta,\\phi)<\/annotation><\/semantics><\/math>-Koordinatenraum,\nkein direktes dreidimensionales Winkelmaß und noch kein vollständiger\nJet-Algorithmus.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Der Azimutunterschied wird auf den Hauptbereich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>−<\/mi><mi>π<\/mi><mo>,<\/mo><mi>π<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(-\\pi,\\pi]<\/annotation><\/semantics><\/math>\nzurückgeführt. Dann gelten\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>η<\/mi><mo>=<\/mo><msub><mi>η<\/mi><mn>1<\/mn><\/msub><mo>−<\/mo><msub><mi>η<\/mi><mn>2<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">\\Delta\\eta=\\eta_1-\\eta_2<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>R<\/mi><mo>=<\/mo><msqrt><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"normal\">Δ<\/mi><mi>η<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo>+<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"normal\">Δ<\/mi><mi>ϕ<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><\/mrow><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">\\Delta R=\\sqrt{(\\Delta\\eta)^2+(\\Delta\\phi)^2}<\/annotation><\/semantics><\/math>.\nDie Nähe zweier Objekte allein entscheidet nicht, ob ein\nAnti-<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>k<\/mi><mi>t<\/mi><\/msub><annotation encoding=\"application/x-tex\">k_t<\/annotation><\/semantics><\/math>-Algorithmus\nsie zusammenfasst: dieser benutzt zusätzlich transversale Impulse und\neine definierte iterative Distanzmetrik.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>R<\/mi><mo>=<\/mo><msqrt><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>η<\/mi><mn>1<\/mn><\/msub><mo>−<\/mo><msub><mi>η<\/mi><mn>2<\/mn><\/msub><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo>+<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"normal\">Δ<\/mi><mi>ϕ<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><\/mrow><\/msqrt><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\Delta R=\\sqrt{(\\eta_1-\\eta_2)^2+(\\Delta\\phi)^2}.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Wähle zwei konstruierte Richtungen mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>η<\/mi><mn>1<\/mn><\/msub><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\eta_1=1{,}2<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>η<\/mi><mn>2<\/mn><\/msub><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>6<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\eta_2=1{,}6<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>ϕ<\/mi><mn>1<\/mn><\/msub><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\phi_1=0{,}2<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>ϕ<\/mi><mn>2<\/mn><\/msub><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>5<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\phi_2=0{,}5<\/annotation><\/semantics><\/math>\nRadiant. Die Differenzen betragen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi mathvariant=\"normal\">Δ<\/mi><mi>η<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">|\\Delta\\eta|=0{,}4<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi mathvariant=\"normal\">Δ<\/mi><mi>ϕ<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">|\\Delta\\phi|=0{,}3<\/annotation><\/semantics><\/math>,\nalso\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>R<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>5<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\Delta R=0{,}5<\/annotation><\/semantics><\/math>.\nDie Zeichnung verwendet einen frei gewählten Radius\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>R<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>6<\/mn><\/mrow><annotation encoding=\"application/x-tex\">R_0=0{,}6<\/annotation><\/semantics><\/math>\nzur Veranschaulichung einer Nachbarschaft.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_045_DE.svg\"\nalt=\"Zwei Punkte im Pseudorapidität-Azimut-Raum mit den Abständen 0,4 und 0,3 sowie einem Radius 0,6.\" />\n<figcaption aria-hidden=\"true\">Zwei Punkte im\nPseudorapidität-Azimut-Raum mit den Abständen 0,4 und 0,3 sowie einem\nRadius 0,6.<\/figcaption>\n<\/figure>\n<p><em>Konstruiertes Abstandsbeispiel in Jet-Koordinaten; keine\nClustering-Simulation.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Wie groß ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>R<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\Delta R<\/annotation><\/semantics><\/math>\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>η<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>6<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\Delta\\eta=0{,}6<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>ϕ<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>8<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\Delta\\phi=0{,}8<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Warum muss die Differenz von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mn>179<\/mn><mo>∘<\/mo><\/msup><annotation encoding=\"application/x-tex\">179^\\circ<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>−<\/mi><msup><mn>179<\/mn><mo>∘<\/mo><\/msup><\/mrow><annotation encoding=\"application/x-tex\">-179^\\circ<\/annotation><\/semantics><\/math>\nperiodisch behandelt werden?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Ist die Bedingung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>R<\/mi><mo>&lt;<\/mo><msub><mi>R<\/mi><mn>0<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">\\Delta R&lt;R_0<\/annotation><\/semantics><\/math>\nallein ein\nAnti-<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>k<\/mi><mi>t<\/mi><\/msub><annotation encoding=\"application/x-tex\">k_t<\/annotation><\/semantics><\/math>-Algorithmus?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>R<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\Delta R=1<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Die physikalisch kurze Azimutdifferenz beträgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mn>2<\/mn><mo>∘<\/mo><\/msup><annotation encoding=\"application/x-tex\">2^\\circ<\/annotation><\/semantics><\/math>,\nnicht\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mn>358<\/mn><mo>∘<\/mo><\/msup><annotation encoding=\"application/x-tex\">358^\\circ<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Nein; zusätzlich sind transversale Impulse und Clustering-Schritte\nnötig.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Pseudorapidität nähert die Rapidität nur bei hinreichend kleinen\nTeilchenmassen gegenüber dem Impuls an. Detector-Akzeptanz, Auflösung,\nKalibrierung und Untergrund beeinflussen rekonstruierte Jets. Die Grafik\nbeschreibt ausschließlich ein geometrisches Kriterium.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Neutrinos entziehen sich meist einer direkten Spurmessung und\nerfordern andere Observablen. <a\nhref=\"index.html?course=university_physics&amp;module=M36&amp;lesson=L4&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste Lektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://home.cern/science/physics/12-steps-idea-discovery/\">CERN – 12 Steps from Idea to Discovery<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Rekonstruktion von Spuren und Jets, simulierte Signale und statistische Kontrollen; Fachlicher Bezug zur Lektion: M36-L3 – Streukinematik, Pseudorapidität und Jet-Abstand · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://pdg.lbl.gov/2026/reviews/experimental_methods_and_colliders.html\">Particle Data Group – Review of Particle Physics 2026: Experimental Methods &amp; Colliders<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Review-Verzeichnis zu Detektoren, Beschleunigern und Kollisionsmessungen; nur fachliche Themenzuordnung; Fachlicher Bezug zur Lektion: M36-L3 – Streukinematik, Pseudorapidität und Jet-Abstand · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M36-L4":"<article class=\"lesson-standard\"><h1 id=\"L4\">M36-L4 – Neutrinooszillationen und Massenmischung<\/h1>\n<p><strong>Kursbereich:<\/strong> M36 – Master: Teilchenphysik, Kollisionsexperimente und Beschleuniger<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M34: Quantenüberlagerung; M30:\nStandardmodell.<\/p>\n<p><strong>Lernziel:<\/strong> Eine Übergangswahrscheinlichkeit im\nidealisierten Zweiflavoursystem mit konsistenten Einheiten\nberechnen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Neutrino-Flavourzustände entstehen als Überlagerung von\nMasseneigenzuständen. Unterschiedliche Phasen entlang einer Flugstrecke\nkönnen eine Änderung des beobachteten Flavours bewirken. Das ist eine\nInterferenzerscheinung und ein Hinweis auf nicht vollständig entartete\nNeutrinomassen. Ein reales Experiment benötigt in der Regel drei\nFlavours sowie Materieeffekte und Detektormodelle.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Im Vakuum und in der Zweiflavournäherung ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>ν<\/mi><mi>α<\/mi><\/msub><mo>→<\/mo><msub><mi>ν<\/mi><mi>β<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msup><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mi>θ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><msup><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"normal\">Δ<\/mi><msup><mi>m<\/mi><mn>2<\/mn><\/msup><mi>L<\/mi><mi>/<\/mi><mn>4<\/mn><mi>E<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">P(\\nu_\\alpha\\to\\nu_\\beta)=\\sin^2(2\\theta)\\sin^2(\\Delta m^2L/4E)<\/annotation><\/semantics><\/math>\nin natürlichen Einheiten. Werden\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><msup><mi>m<\/mi><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\Delta m^2<\/annotation><\/semantics><\/math>\nin\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><mn>2<\/mn><\/msup><annotation encoding=\"application/x-tex\">\\mathrm{eV}^2<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>L<\/mi><annotation encoding=\"application/x-tex\">L<\/annotation><\/semantics><\/math>\nin\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">k<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\mathrm{km}<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>E<\/mi><annotation encoding=\"application/x-tex\">E<\/annotation><\/semantics><\/math>\nin\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">G<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\mathrm{GeV}<\/annotation><\/semantics><\/math>\neingesetzt, wird das Phasenargument numerisch\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mo>,<\/mo><mn>267<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">Δ<\/mi><msup><mi>m<\/mi><mn>2<\/mn><\/msup><mi>L<\/mi><mi>/<\/mi><mi>E<\/mi><\/mrow><annotation encoding=\"application/x-tex\">1{,}267\\,\\Delta m^2L/E<\/annotation><\/semantics><\/math>.\nDie Einheitendefinition ist Teil der Formel;\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mo>,<\/mo><mn>267<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1{,}267<\/annotation><\/semantics><\/math>\nist kein dimensionsloser Grundparameter.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mrow><mi>α<\/mi><mo>→<\/mo><mi>β<\/mi><\/mrow><\/msub><mo>=<\/mo><msup><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mi>θ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mspace width=\"0.167em\"><\/mspace><msup><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/msup><mspace width=\"-0.167em\"><\/mspace><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mn>1.267<\/mn><mspace width=\"0.167em\"><\/mspace><mfrac><mrow><mi mathvariant=\"normal\">Δ<\/mi><msup><mi>m<\/mi><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msup><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mi>L<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mrow><mi mathvariant=\"normal\">k<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mrow><mi mathvariant=\"normal\">G<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><\/mfrac><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">P_{\\alpha\\to\\beta}=\\sin^2(2\\theta)\\,\\sin^2\\!\\left(1.267\\,\\frac{\\Delta m^2[\\mathrm{eV}^2]L[\\mathrm{km}]}{E[\\mathrm{GeV}]}\\right).<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Für maximale Mischung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>θ<\/mi><mo>=<\/mo><msup><mn>45<\/mn><mo>∘<\/mo><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\theta=45^\\circ<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><msup><mi>m<\/mi><mn>2<\/mn><\/msup><mo>=<\/mo><mn>2<\/mn><mo>,<\/mo><mn>5<\/mn><mo>×<\/mo><msup><mn>10<\/mn><mrow><mi>−<\/mi><mn>3<\/mn><\/mrow><\/msup><mspace width=\"0.167em\"><\/mspace><msup><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\Delta m^2=2{,}5\\times10^{-3}\\,\\mathrm{eV}^2<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L<\/mi><mo>=<\/mo><mn>500<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">k<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">L=500\\,\\mathrm{km}<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo>=<\/mo><mn>1<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">G<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">E=1\\,\\mathrm{GeV}<\/annotation><\/semantics><\/math>\nist die Phase\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mo>,<\/mo><mn>58375<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1{,}58375<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo>≈<\/mo><mn>0<\/mn><mo>,<\/mo><mn>9998<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P\\approx0{,}9998<\/annotation><\/semantics><\/math>.\nDie Grafik zeigt das idealisierte Schwingungsmuster als Funktion von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L<\/mi><mi>/<\/mi><mi>E<\/mi><\/mrow><annotation encoding=\"application/x-tex\">L/E<\/annotation><\/semantics><\/math>,\nnicht den Wirkungsquerschnitt eines Detektors.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_187_DE.svg\"\nalt=\"Sinusquadratische Neutrinoübergangswahrscheinlichkeit gegen Flugstrecke bei maximalem Mischungswinkel.\" />\n<figcaption aria-hidden=\"true\">Sinusquadratische\nNeutrinoübergangswahrscheinlichkeit gegen Flugstrecke bei maximalem\nMischungswinkel.<\/figcaption>\n<\/figure>\n<p><em>Zweiflavoursystem im Vakuum mit konstruierten\nParametern.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Was ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>P<\/mi><annotation encoding=\"application/x-tex\">P<\/annotation><\/semantics><\/math>\nbei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>θ<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\theta=0<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Wie ändert sich die Oszillationsphase bei verdoppeltem\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>E<\/mi><annotation encoding=\"application/x-tex\">E<\/annotation><\/semantics><\/math>\nund festem\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>L<\/mi><annotation encoding=\"application/x-tex\">L<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Welche Einheit ist für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>L<\/mi><annotation encoding=\"application/x-tex\">L<\/annotation><\/semantics><\/math>\nin der numerischen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mo>,<\/mo><mn>267<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1{,}267<\/annotation><\/semantics><\/math>-Formel\nvorausgesetzt?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P=0<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Sie halbiert sich.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Kilometer.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Das Zwei-Flavour-Vakuummodell vernachlässigt\ndrei-Flavour-Interferenz, CP-Phase, Materieeffekte und endliche\nEnergieauflösung. Die hier verwendeten Parameter sind ein\nRechenbeispiel, keine aktuelle globale Parameterschätzung.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Schwerionenkollisionen erlauben einen völlig anderen Zugang zur\nVielteilchendynamik. <a href=\"index.html?course=university_physics&amp;module=M36&amp;lesson=L5&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste\nLektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://pdg.lbl.gov/2026/reviews/standard_model_and_related.html\">Particle Data Group – Review of Particle Physics 2026: Standard Model &amp; Related Topics<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachreview-Verzeichnis zu Eichwechselwirkungen, Quarks und Neutrinos; einzelne Gleichungen werden hier eigenständig hergeleitet; Fachlicher Bezug zur Lektion: M36-L4 – Neutrinooszillationen und Massenmischung · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M36-L5":"<article class=\"lesson-standard\"><h1 id=\"L5\">M36-L5 – Schwerionenkollisionen, Quark-Gluon-Plasma und Fluss<\/h1>\n<p><strong>Kursbereich:<\/strong> M36 – Master: Teilchenphysik, Kollisionsexperimente und Beschleuniger<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M27: Vielteilchentheorie; M30:\nQCD.<\/p>\n<p><strong>Lernziel:<\/strong> Den elliptischen Flusskoeffizienten als\nFourier-Moment erläutern und ein normiertes Winkelmodell auswerten.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Bei ultrarelativistischen Kern-Kern-Stößen kann stark wechselwirkende\nMaterie kurzzeitig unter extremen Energiedichten entstehen. Experimente\nwie ALICE untersuchen kollektive Teilchenverteilungen und\nJet-Modifikationen, um Eigenschaften des Quark-Gluon-Plasmas\neinzugrenzen. Eine anisotrope Winkelverteilung ist eine\nObservablenklasse, nicht für sich allein eine vollständige\nZustandsdiagnose.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Für den Winkel\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>φ<\/mi><annotation encoding=\"application/x-tex\">\\varphi<\/annotation><\/semantics><\/math>\nrelativ zur Ereignisebene\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi mathvariant=\"normal\">Ψ<\/mi><mn>2<\/mn><\/msub><annotation encoding=\"application/x-tex\">\\Psi_2<\/annotation><\/semantics><\/math>\ndefiniert man\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>v<\/mi><mn>2<\/mn><\/msub><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><mrow><mi mathvariant=\"normal\">cos<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>φ<\/mi><mo>−<\/mo><msub><mi mathvariant=\"normal\">Ψ<\/mi><mn>2<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><\/mrow><annotation encoding=\"application/x-tex\">v_2=\\langle\\cos 2(\\varphi-\\Psi_2)\\rangle<\/annotation><\/semantics><\/math>.\nEin vereinfachtes normiertes Einharmonisches Modell lautet\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>φ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>+<\/mo><mn>2<\/mn><msub><mi>v<\/mi><mn>2<\/mn><\/msub><mrow><mi mathvariant=\"normal\">cos<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>φ<\/mi><mo>−<\/mo><msub><mi mathvariant=\"normal\">Ψ<\/mi><mn>2<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mi>π<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">f(\\varphi)=(1+2v_2\\cos2(\\varphi-\\Psi_2))/(2\\pi)<\/annotation><\/semantics><\/math>.\nDas Integral über\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mn>0<\/mn><annotation encoding=\"application/x-tex\">0<\/annotation><\/semantics><\/math>\nbis\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mi>π<\/mi><\/mrow><annotation encoding=\"application/x-tex\">2\\pi<\/annotation><\/semantics><\/math>\nist eins. Für dieses reine Einzelharmonischenmodell muss\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi>v<\/mi><mn>2<\/mn><\/msub><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>≤<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">|v_2|\\le1/2<\/annotation><\/semantics><\/math>\ngelten, damit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo>≥<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">f\\ge0<\/annotation><\/semantics><\/math>\nbleibt; reale Messungen verwenden weitere Harmonische und\nKorrekturen.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>v<\/mi><mn>2<\/mn><\/msub><mo>=<\/mo><mrow><mo stretchy=\"true\" form=\"prefix\">⟨<\/mo><mi mathvariant=\"normal\">cos<\/mi><mo minsize=\"120%\" maxsize=\"120%\" stretchy=\"true\" form=\"prefix\">(<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>φ<\/mi><mo>−<\/mo><msub><mi mathvariant=\"normal\">Ψ<\/mi><mn>2<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo minsize=\"120%\" maxsize=\"120%\" stretchy=\"true\" form=\"postfix\">)<\/mo><mo stretchy=\"true\" form=\"postfix\">⟩<\/mo><\/mrow><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">v_2=\\left\\langle\\cos\\bigl(2(\\varphi-\\Psi_2)\\bigr)\\right\\rangle.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Wähle\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>v<\/mi><mn>2<\/mn><\/msub><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>10<\/mn><\/mrow><annotation encoding=\"application/x-tex\">v_2=0{,}10<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi mathvariant=\"normal\">Ψ<\/mi><mn>2<\/mn><\/msub><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\Psi_2=0<\/annotation><\/semantics><\/math>.\nDie unnormierte Winkeldichte ist bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>φ<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\varphi=0<\/annotation><\/semantics><\/math>\nproportional zu\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mo>,<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1{,}2<\/annotation><\/semantics><\/math>\nund bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>φ<\/mi><mo>=<\/mo><mi>π<\/mi><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\varphi=\\pi/2<\/annotation><\/semantics><\/math>\nzu\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>,<\/mo><mn>8<\/mn><\/mrow><annotation encoding=\"application/x-tex\">0{,}8<\/annotation><\/semantics><\/math>;\ndas Verhältnis beträgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mo>,<\/mo><mn>5<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1{,}5<\/annotation><\/semantics><\/math>.\nDie polare Kurve ist rein illustrativ und nicht einem realen Datensatz\nentnommen.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_130_DE.svg\"\nalt=\"Polare geschlossene Kurve mit leicht länglicher Teilchenabstrahlung und zwei Hauptachsen.\" />\n<figcaption aria-hidden=\"true\">Polare geschlossene Kurve mit leicht\nlänglicher Teilchenabstrahlung und zwei Hauptachsen.<\/figcaption>\n<\/figure>\n<p><em>Konstruierte elliptische Flussverteilung mit v2 gleich\n0,10.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Was ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>v<\/mi><mn>2<\/mn><\/msub><annotation encoding=\"application/x-tex\">v_2<\/annotation><\/semantics><\/math>\nbei einer exakt azimutal gleichmäßigen Verteilung?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Berechne\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>+<\/mo><mn>2<\/mn><msub><mi>v<\/mi><mn>2<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>−<\/mo><mn>2<\/mn><msub><mi>v<\/mi><mn>2<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(1+2v_2)/(1-2v_2)<\/annotation><\/semantics><\/math>\nbei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>v<\/mi><mn>2<\/mn><\/msub><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">v_2=0{,}2<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum ist elliptischer Fluss allein kein eindeutiger\nQuark-Gluon-Plasma-Beweis?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>v<\/mi><mn>2<\/mn><\/msub><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">v_2=0<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mo>,<\/mo><mn>4<\/mn><mi>/<\/mi><mn>0<\/mn><mo>,<\/mo><mn>6<\/mn><mo>=<\/mo><mn>7<\/mn><mi>/<\/mi><mn>3<\/mn><mo>≈<\/mo><mn>2<\/mn><mo>,<\/mo><mn>33<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1{,}4/0{,}6=7/3\\approx2{,}33<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Weitere Effekte, Systemgröße und Modellannahmen müssen kontrolliert\nwerden.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Das Beispiel ignoriert Fluktuationen der Ereignisebene,\nNichtfluss-Korrelationen, zentrale Kollisionsgeometrie und weitere\nFourier-Komponenten. Aussagen über Hydrodynamik sind modell- und\nobservablenübergreifend abzusichern.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Der nächste Schwerpunkt ist die kontrollierte Formung von\nTeilchenstrahlen vor der Kollision. <a\nhref=\"index.html?course=university_physics&amp;module=M36&amp;lesson=L6&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste Lektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://alice.cern/alice-physics/\">CERN ALICE – ALICE Physics<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Schwerionenkollisionen und stark wechselwirkende Materie; keine direkte Herleitung der Flussformel; Fachlicher Bezug zur Lektion: M36-L5 – Schwerionenkollisionen, Quark-Gluon-Plasma und Fluss · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://home.cern/science/physics/heavy-ions-and-quark-gluon-plasma/\">CERN – Heavy Ions and Quark-Gluon Plasma<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Schwerionenexperiment und Jet-Quenching als physikalischer Kontext; Fachlicher Bezug zur Lektion: M36-L5 – Schwerionenkollisionen, Quark-Gluon-Plasma und Fluss · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M36-L6":"<article class=\"lesson-standard\"><h1 id=\"L6\">M36-L6 – Transversale Strahloptik und RMS-Emittanz<\/h1>\n<p><strong>Kursbereich:<\/strong> M36 – Master: Teilchenphysik, Kollisionsexperimente und Beschleuniger<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M31: lineare Systeme und Numerik;\nM32: Beschleunigertechnik.<\/p>\n<p><strong>Lernziel:<\/strong> Eine geometrische RMS-Emittanz aus\nzentrierten Phasenraum-Momenten berechnen und ihre lineare\nTransportinvarianz bedingt begründen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Ein geladenes Teilchenbündel wird transversal durch Ort\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>x<\/mi><annotation encoding=\"application/x-tex\">x<\/annotation><\/semantics><\/math>\nund kleinen Richtungswinkel\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>x<\/mi><mi>′<\/mi><\/msup><mo>≃<\/mo><msub><mi>p<\/mi><mi>x<\/mi><\/msub><mi>/<\/mi><msub><mi>p<\/mi><mi>z<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">x^{\\prime}\\simeq p_x/p_z<\/annotation><\/semantics><\/math>\nbeschrieben. Eine dünne fokussierende Linse ändert im paraxialen Modell\nden Winkel nach\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>x<\/mi><mrow><mi mathvariant=\"normal\">o<\/mi><mi mathvariant=\"normal\">u<\/mi><mi mathvariant=\"normal\">t<\/mi><\/mrow><mi>′<\/mi><\/msubsup><mo>=<\/mo><msubsup><mi>x<\/mi><mrow><mi mathvariant=\"normal\">i<\/mi><mi mathvariant=\"normal\">n<\/mi><\/mrow><mi>′<\/mi><\/msubsup><mo>−<\/mo><mi>x<\/mi><mi>/<\/mi><mi>f<\/mi><\/mrow><annotation encoding=\"application/x-tex\">x^{\\prime}_{\\mathrm{out}}=x^{\\prime}_{\\mathrm{in}}-x/f<\/annotation><\/semantics><\/math>,\nwährend\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>x<\/mi><annotation encoding=\"application/x-tex\">x<\/annotation><\/semantics><\/math>\nan der Linse unverändert bleibt. Ein Strahl ist eine Verteilung im\nPhasenraum und nicht nur ein einzelner Strahlengang.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Für die zentrierten Variablen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>X<\/mi><mo>=<\/mo><mi>x<\/mi><mo>−<\/mo><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><\/mrow><annotation encoding=\"application/x-tex\">X=x-\\langle x\\rangle<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>X<\/mi><mi>′<\/mi><\/msup><mo>=<\/mo><msup><mi>x<\/mi><mi>′<\/mi><\/msup><mo>−<\/mo><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><msup><mi>x<\/mi><mi>′<\/mi><\/msup><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><\/mrow><annotation encoding=\"application/x-tex\">X^{\\prime}=x^{\\prime}-\\langle x^{\\prime}\\rangle<\/annotation><\/semantics><\/math>\nlautet die Kovarianzmatrix\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Σ<\/mi><mo>=<\/mo><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mtable><mtr><mtd columnalign=\"center\" class=\"text-center\"><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><msup><mi>X<\/mi><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><mi>X<\/mi><msup><mi>X<\/mi><mi>′<\/mi><\/msup><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><mi>X<\/mi><msup><mi>X<\/mi><mi>′<\/mi><\/msup><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><msup><mi>X<\/mi><mrow><mi>′<\/mi><mn>2<\/mn><\/mrow><\/msup><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><\/mtd><\/mtr><\/mtable><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\Sigma=\\begin{pmatrix}\\langle X^2\\rangle&amp;\\langle XX^{\\prime}\\rangle\\\\\\langle XX^{\\prime}\\rangle&amp;\\langle X^{\\prime2}\\rangle\\end{pmatrix}<\/annotation><\/semantics><\/math>.\nDie geometrische RMS-Emittanz ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>ε<\/mi><mrow><mi mathvariant=\"normal\">r<\/mi><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/msub><mo>=<\/mo><msqrt><mrow><mrow><mi mathvariant=\"normal\">det<\/mi><mo>&#8289;<\/mo><\/mrow><mi mathvariant=\"normal\">Σ<\/mi><\/mrow><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">\\varepsilon_{\\mathrm{rms}}=\\sqrt{\\det\\Sigma}<\/annotation><\/semantics><\/math>\n(Einheit z. B. mm mrad). Bei linearem Transport\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi mathvariant=\"normal\">Σ<\/mi><mrow><mi mathvariant=\"normal\">o<\/mi><mi mathvariant=\"normal\">u<\/mi><mi mathvariant=\"normal\">t<\/mi><\/mrow><\/msub><mo>=<\/mo><mi>R<\/mi><msub><mi mathvariant=\"normal\">Σ<\/mi><mrow><mi mathvariant=\"normal\">i<\/mi><mi mathvariant=\"normal\">n<\/mi><\/mrow><\/msub><msup><mi>R<\/mi><mi>T<\/mi><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\Sigma_{\\mathrm{out}}=R\\Sigma_{\\mathrm{in}}R^T<\/annotation><\/semantics><\/math>\nfolgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>ε<\/mi><mrow><mi mathvariant=\"normal\">o<\/mi><mi mathvariant=\"normal\">u<\/mi><mi mathvariant=\"normal\">t<\/mi><\/mrow><\/msub><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mrow><mi mathvariant=\"normal\">det<\/mi><mo>&#8289;<\/mo><\/mrow><mi>R<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi>ε<\/mi><mrow><mi mathvariant=\"normal\">i<\/mi><mi mathvariant=\"normal\">n<\/mi><\/mrow><\/msub><\/mrow><annotation encoding=\"application/x-tex\">\\varepsilon_{\\mathrm{out}}=|\\det R|\\varepsilon_{\\mathrm{in}}<\/annotation><\/semantics><\/math>.\nDie dünne Linse hat\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R<\/mi><mo>=<\/mo><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mtable><mtr><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>0<\/mn><\/mtd><\/mtr><mtr><mtd columnalign=\"center\" class=\"text-center\"><mi>−<\/mi><mn>1<\/mn><mi>/<\/mi><mi>f<\/mi><\/mtd><mtd columnalign=\"center\" class=\"text-center\"><mn>1<\/mn><\/mtd><\/mtr><\/mtable><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">R=\\begin{pmatrix}1&amp;0\\\\-1/f&amp;1\\end{pmatrix}<\/annotation><\/semantics><\/math>\nund Determinante eins.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>ε<\/mi><mrow><mi mathvariant=\"normal\">r<\/mi><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/msub><mo>=<\/mo><msqrt><mrow><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><msup><mi>X<\/mi><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><msup><mi>X<\/mi><mrow><mi>′<\/mi><mn>2<\/mn><\/mrow><\/msup><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo>−<\/mo><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><mi>X<\/mi><msup><mi>X<\/mi><mi>′<\/mi><\/msup><msup><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mn>2<\/mn><\/msup><\/mrow><\/msqrt><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\varepsilon_{\\mathrm{rms}}=\\sqrt{\\langle X^2\\rangle\\langle X^{\\prime2}\\rangle-\\langle XX^{\\prime}\\rangle^2}.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Sei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>σ<\/mi><mi>x<\/mi><\/msub><mo>=<\/mo><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\sigma_x=2\\,\\mathrm{mm}<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>σ<\/mi><msup><mi>x<\/mi><mi>′<\/mi><\/msup><\/msub><mo>=<\/mo><mn>1<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">r<\/mi><mi mathvariant=\"normal\">a<\/mi><mi mathvariant=\"normal\">d<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\sigma_{x^{\\prime}}=1\\,\\mathrm{mrad}<\/annotation><\/semantics><\/math>\nund die Korrelation\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ρ<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>6<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\rho=0{,}6<\/annotation><\/semantics><\/math>.\nDann ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><mi>X<\/mi><msup><mi>X<\/mi><mi>′<\/mi><\/msup><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo>=<\/mo><mi>ρ<\/mi><msub><mi>σ<\/mi><mi>x<\/mi><\/msub><msub><mi>σ<\/mi><msup><mi>x<\/mi><mi>′<\/mi><\/msup><\/msub><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">m<\/mi><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">r<\/mi><mi mathvariant=\"normal\">a<\/mi><mi mathvariant=\"normal\">d<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\langle XX^{\\prime}\\rangle=\\rho\\sigma_x\\sigma_{x^{\\prime}}=1{,}2\\,\\mathrm{mm\\,mrad}<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>ε<\/mi><mrow><mi mathvariant=\"normal\">r<\/mi><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/msub><mo>=<\/mo><mn>2<\/mn><msqrt><mrow><mn>1<\/mn><mo>−<\/mo><mn>0<\/mn><mo>,<\/mo><msup><mn>6<\/mn><mn>2<\/mn><\/msup><\/mrow><\/msqrt><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>6<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">m<\/mi><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">r<\/mi><mi mathvariant=\"normal\">a<\/mi><mi mathvariant=\"normal\">d<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\varepsilon_{\\mathrm{rms}}=2\\sqrt{1-0{,}6^2}=1{,}6\\,\\mathrm{mm\\,mrad}<\/annotation><\/semantics><\/math>.\nDie Grafik zeigt ein originäres phasenräumliches\nKonfidenz-Ellipsenschema; die Ellipsenfläche hängt von der gewählten\nKontur ab.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_300_DE.svg\"\nalt=\"Geneigte Ellipse im transversalen Phasenraum, mit Mittelwerten null und markierten RMS-Achsen.\" />\n<figcaption aria-hidden=\"true\">Geneigte Ellipse im transversalen\nPhasenraum, mit Mittelwerten null und markierten\nRMS-Achsen.<\/figcaption>\n<\/figure>\n<p><em>Kovarianzellipse einer konstruierten transversalen\nStrahlverteilung.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Welche RMS-Emittanz ergibt sich für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ρ<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\rho=0<\/annotation><\/semantics><\/math>\nbei denselben Streuungen?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Wie verändert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">det<\/mi><mo>&#8289;<\/mo><\/mrow><mi>R<\/mi><mo>=<\/mo><mi>−<\/mi><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\det R=-1<\/annotation><\/semantics><\/math>\nden Betrag der RMS-Emittanz bei linearer Abbildung?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum ist die geometrische Emittanz bei Beschleunigung nicht ohne\nZusatzannahmen invariant?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">m<\/mi><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">r<\/mi><mi mathvariant=\"normal\">a<\/mi><mi mathvariant=\"normal\">d<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">2\\,\\mathrm{mm\\,mrad}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Der Betrag bleibt erhalten, denn\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mrow><mi mathvariant=\"normal\">det<\/mi><mo>&#8289;<\/mo><\/mrow><mi>R<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">|\\det R|=1<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Da\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>x<\/mi><mi>′<\/mi><\/msup><mo>≃<\/mo><msub><mi>p<\/mi><mi>x<\/mi><\/msub><mi>/<\/mi><msub><mi>p<\/mi><mi>z<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">x^{\\prime}\\simeq p_x/p_z<\/annotation><\/semantics><\/math>\nsich mit dem longitudinalen Impuls skaliert; normierte Emittanz\nerfordert eigene Annahmen.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Die Aussage betrifft eine entkoppelte lineare 2D-Phasebene bei festen\nKoordinaten und ohne relevante nichtlineare Kräfte, Raumladung oder\nStreuung. In Beschleunigungsabschnitten, bei Kopplungen und\nnichtlinearen Strukturen ist Erhaltung nicht pauschal gegeben.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Die Detektoren rekonstruieren anschließend die gekrümmten\nTeilchenspuren aus Kollisionen. <a\nhref=\"index.html?course=university_physics&amp;module=M36&amp;lesson=L7&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste Lektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://videos.cern.ch/record/3025960\">CERN CDS – Transverse Beam Dynamics III<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Metadateneintrag zu transversaler Strahldynamik; nicht als Emittanzformel-Beleg verwendet; Fachlicher Bezug zur Lektion: M36-L6 – Transversale Strahloptik und RMS-Emittanz · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://pdg.lbl.gov/2026/reviews/experimental_methods_and_colliders.html\">Particle Data Group – Review of Particle Physics 2026: Experimental Methods &amp; Colliders<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Review-Verzeichnis zu Detektoren, Beschleunigern und Kollisionsmessungen; nur fachliche Themenzuordnung; Fachlicher Bezug zur Lektion: M36-L6 – Transversale Strahloptik und RMS-Emittanz · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M36-L7":"<article class=\"lesson-standard\"><h1 id=\"L7\">M36-L7 – Spurdetektoren, Magnetfeldkrümmung und Impuls<\/h1>\n<p><strong>Kursbereich:<\/strong> M36 – Master: Teilchenphysik, Kollisionsexperimente und Beschleuniger<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M10: Lorentzkraft; M36-L6:\nTeilchenstrahlen.<\/p>\n<p><strong>Lernziel:<\/strong> Aus einem idealen Kreisbahnradius im\nhomogenen Magnetfeld den transversalen Impuls berechnen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Spurdetektoren registrieren Messpunkte, aus denen in einem Magnetfeld\ndie Bahn geladener Teilchen rekonstruiert wird. Die Krümmungsrichtung\nhängt vom Ladungsvorzeichen ab; der Radius liefert bei bekannter\nFeldstärke einen Impulshinweis. Kalorimeter erfassen deponierte Energie,\nwährend Myonkammern besonders durchdringende geladene Teilchen\nnachweisen. Diese Subsysteme ergänzen sich.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Für eine Teilchenladung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>q<\/mi><annotation encoding=\"application/x-tex\">q<\/annotation><\/semantics><\/math>,\nsenkrechte Impulskomponente\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>p<\/mi><mi>T<\/mi><\/msub><annotation encoding=\"application/x-tex\">p_T<\/annotation><\/semantics><\/math>\nund homogenes\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>B<\/mi><annotation encoding=\"application/x-tex\">B<\/annotation><\/semantics><\/math>\nwirkt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>q<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi>v<\/mi><mi>T<\/mi><\/msub><mi>B<\/mi><mo>=<\/mo><msub><mi>p<\/mi><mi>T<\/mi><\/msub><msub><mi>v<\/mi><mi>T<\/mi><\/msub><mi>/<\/mi><mi>R<\/mi><\/mrow><annotation encoding=\"application/x-tex\">|q|v_TB=p_Tv_T/R<\/annotation><\/semantics><\/math>,\nalso\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>p<\/mi><mi>T<\/mi><\/msub><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>q<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>B<\/mi><mi>R<\/mi><\/mrow><annotation encoding=\"application/x-tex\">p_T=|q|BR<\/annotation><\/semantics><\/math>.\nIn praktischen Einheiten gilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>p<\/mi><mi>T<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mrow><mi mathvariant=\"normal\">G<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><mi>/<\/mi><mi>c<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>≃<\/mo><mn>0<\/mn><mo>,<\/mo><mn>2998<\/mn><mspace width=\"0.167em\"><\/mspace><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>q<\/mi><mi>/<\/mi><mi>e<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>B<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi mathvariant=\"normal\">T<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mi>R<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi mathvariant=\"normal\">m<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">p_T[\\mathrm{GeV}/c]\\simeq0{,}2998\\,|q/e|B[\\mathrm T]R[\\mathrm m]<\/annotation><\/semantics><\/math>.\nDie Näherung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>,<\/mo><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">0{,}3<\/annotation><\/semantics><\/math>\nberuht auf Einheitenumrechnung, nicht auf einem experimentellen Fit.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>p<\/mi><mi>T<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mrow><mi mathvariant=\"normal\">G<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><mi>/<\/mi><mi>c<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>≃<\/mo><mn>0.2998<\/mn><mspace width=\"0.167em\"><\/mspace><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>q<\/mi><mi>/<\/mi><mi>e<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mspace width=\"0.167em\"><\/mspace><mi>B<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi mathvariant=\"normal\">T<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mi>R<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi mathvariant=\"normal\">m<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">p_T[\\mathrm{GeV}/c]\\simeq0.2998\\,|q/e|\\,B[\\mathrm T]R[\\mathrm m].<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Für ein einfach geladenes Teilchen bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>B<\/mi><mo>=<\/mo><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">T<\/mi><\/mrow><annotation encoding=\"application/x-tex\">B=2\\,\\mathrm T<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R<\/mi><mo>=<\/mo><mn>1<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">m<\/mi><\/mrow><annotation encoding=\"application/x-tex\">R=1\\,\\mathrm m<\/annotation><\/semantics><\/math>\nfolgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>p<\/mi><mi>T<\/mi><\/msub><mo>≈<\/mo><mn>0<\/mn><mo>,<\/mo><mn>600<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">G<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><mi>/<\/mi><mi>c<\/mi><\/mrow><annotation encoding=\"application/x-tex\">p_T\\approx0{,}600\\,\\mathrm{GeV}/c<\/annotation><\/semantics><\/math>.\nEine zweite Spur mit doppeltem Radius bei identischer Ladung und\ndemselben Feld hätte den doppelten transversalen Impuls. Die Zeichnung\nzeigt ein frei konstruiertes Schichtmodell mit zwei gekrümmten\nBahnen.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_299_DE.svg\"\nalt=\"Schematische Ringlagen eines Spurdetektors mit zwei geladenen gekrümmten Bahnen und Magnetfeldrichtung.\" />\n<figcaption aria-hidden=\"true\">Schematische Ringlagen eines\nSpurdetektors mit zwei geladenen gekrümmten Bahnen und\nMagnetfeldrichtung.<\/figcaption>\n<\/figure>\n<p><em>Vereinfachter Magnetspur-Nachweis im Kollisionsdetektor.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Wie groß ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>p<\/mi><mi>T<\/mi><\/msub><annotation encoding=\"application/x-tex\">p_T<\/annotation><\/semantics><\/math>\nbei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>B<\/mi><mo>=<\/mo><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">T<\/mi><\/mrow><annotation encoding=\"application/x-tex\">B=2\\,\\mathrm T<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>5<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">m<\/mi><\/mrow><annotation encoding=\"application/x-tex\">R=0{,}5\\,\\mathrm m<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>q<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>=<\/mo><mi>e<\/mi><\/mrow><annotation encoding=\"application/x-tex\">|q|=e<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Welchen Radius hat eine gleich geladene Spur mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>p<\/mi><mi>T<\/mi><\/msub><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">G<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><mi>/<\/mi><mi>c<\/mi><\/mrow><annotation encoding=\"application/x-tex\">p_T=1{,}2\\,\\mathrm{GeV}/c<\/annotation><\/semantics><\/math>\nbei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>B<\/mi><mo>=<\/mo><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">T<\/mi><\/mrow><annotation encoding=\"application/x-tex\">B=2\\,\\mathrm T<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum liefert eine neutrale Teilchenspur keine Krümmungsinformation\nim Magnetfeld?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>p<\/mi><mi>T<\/mi><\/msub><mo>≈<\/mo><mn>0<\/mn><mo>,<\/mo><mn>300<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">G<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><mi>/<\/mi><mi>c<\/mi><\/mrow><annotation encoding=\"application/x-tex\">p_T\\approx0{,}300\\,\\mathrm{GeV}/c<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R<\/mi><mo>≈<\/mo><mn>2<\/mn><mo>,<\/mo><mn>00<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">m<\/mi><\/mrow><annotation encoding=\"application/x-tex\">R\\approx2{,}00\\,\\mathrm m<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Ohne Ladung wirkt die magnetische Lorentzkraft nicht; neutrale\nTeilchen erfordern andere Nachweismethoden.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Die einfache Kreisbahn setzt ein konstantes Feld, verlustarme\nBewegung und bekannte Projektion voraus. Reale Spurrekonstruktion\nbenötigt Feldkarten, Mehrfachstreuung, Material- und\nAlignmentskorrekturen und eine Unsicherheitsabschätzung.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Die letzte Lektion behandelt die statistische Unterscheidung von\nSignal und Hintergrund. <a href=\"index.html?course=university_physics&amp;module=M36&amp;lesson=L8&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste\nLektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://home.cern/science/experiments/how-detector-works/\">CERN – How a Detector Works<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Spurdetektoren, Kalorimeter und Teilchenidentifikation; kein Zahlenbeleg für das Modellbeispiel; Fachlicher Bezug zur Lektion: M36-L7 – Spurdetektoren, Magnetfeldkrümmung und Impuls · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://pdg.lbl.gov/2026/reviews/experimental_methods_and_colliders.html\">Particle Data Group – Review of Particle Physics 2026: Experimental Methods &amp; Colliders<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Review-Verzeichnis zu Detektoren, Beschleunigern und Kollisionsmessungen; nur fachliche Themenzuordnung; Fachlicher Bezug zur Lektion: M36-L7 – Spurdetektoren, Magnetfeldkrümmung und Impuls · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M36-L8":"<article class=\"lesson-standard\"><h1 id=\"L8\">M36-L8 – Zählexperimente, Likelihood und statistische Evidenz<\/h1>\n<p><strong>Kursbereich:<\/strong> M36 – Master: Teilchenphysik, Kollisionsexperimente und Beschleuniger<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M13: Statistik; M31:\nModellvalidierung; M32: Zählmessung.<\/p>\n<p><strong>Lernziel:<\/strong> Die Asimov-Formel für einen einfachen,\nhintergrundbekannten Zählkanal anwenden und ihre Grenzen benennen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Teilchenexperimente unterscheiden ein mögliches Signal von bekannten\nund unbekannten Untergrundprozessen. Ein einfacher Zählkanal wird häufig\nmit einer Poisson-Likelihood beschrieben. Die Aussagekraft hängt nicht\nnur von der Differenz der Zählzahlen ab, sondern auch von der\nUnsicherheit des Untergrunds und der Wahl eines Testmodells. Ein\nüberschüssiger Zählwert ist nicht automatisch eine Entdeckung.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Für die angenommene Signal-Erwartung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s<\/mi><mo>≥<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">s\\ge0<\/annotation><\/semantics><\/math>\nund einen exakt bekannten Untergrund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>b<\/mi><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">b&gt;0<\/annotation><\/semantics><\/math>\nnutzt man im einfachen Asimov-Zählmodell\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Z<\/mi><mi>A<\/mi><\/msub><mo>=<\/mo><msqrt><mrow><mn>2<\/mn><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>s<\/mi><mo>+<\/mo><mi>b<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mrow><mi mathvariant=\"normal\">ln<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>+<\/mo><mi>s<\/mi><mi>/<\/mi><mi>b<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><mi>s<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">Z_A=\\sqrt{2[(s+b)\\ln(1+s/b)-s]}<\/annotation><\/semantics><\/math>.\nIm Grenzfall\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s<\/mi><mo>≪<\/mo><mi>b<\/mi><\/mrow><annotation encoding=\"application/x-tex\">s\\ll b<\/annotation><\/semantics><\/math>\nnähert sich dies\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s<\/mi><mi>/<\/mi><msqrt><mi>b<\/mi><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">s/\\sqrt b<\/annotation><\/semantics><\/math>\nan. Diese Größe ist die erwartete asymptotische Signifikanz im Modell\nund weder ein beobachteter p-Wert noch bei unsicherem Untergrund\nallgemein gültig.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Z<\/mi><mi>A<\/mi><\/msub><mo>=<\/mo><msqrt><mrow><mn>2<\/mn><mrow><mo stretchy=\"true\" form=\"prefix\">[<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>s<\/mi><mo>+<\/mo><mi>b<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi mathvariant=\"normal\">ln<\/mi><mspace width=\"-0.167em\"><\/mspace><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>+<\/mo><mfrac><mi>s<\/mi><mi>b<\/mi><\/mfrac><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><mo>−<\/mo><mi>s<\/mi><mo stretchy=\"true\" form=\"postfix\">]<\/mo><\/mrow><\/mrow><\/msqrt><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">Z_A=\\sqrt{2\\left[(s+b)\\ln\\!\\left(1+\\frac{s}{b}\\right)-s\\right]}.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>b<\/mi><mo>=<\/mo><mn>100<\/mn><\/mrow><annotation encoding=\"application/x-tex\">b=100<\/annotation><\/semantics><\/math>\nund ein hypothetisches erwartetes Signal\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s<\/mi><mo>=<\/mo><mn>25<\/mn><\/mrow><annotation encoding=\"application/x-tex\">s=25<\/annotation><\/semantics><\/math>\nergibt sich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Z<\/mi><mi>A<\/mi><\/msub><mo>≈<\/mo><mn>2<\/mn><mo>,<\/mo><mn>405<\/mn><\/mrow><annotation encoding=\"application/x-tex\">Z_A\\approx2{,}405<\/annotation><\/semantics><\/math>.\nDie Näherung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s<\/mi><mi>/<\/mi><msqrt><mi>b<\/mi><\/msqrt><mo>=<\/mo><mn>2<\/mn><mo>,<\/mo><mn>5<\/mn><\/mrow><annotation encoding=\"application/x-tex\">s/\\sqrt b=2{,}5<\/annotation><\/semantics><\/math>\nist hier etwas größer. In der Grafik werden beide Werte als reine\nModellvergleichsbalken dargestellt, nicht als reale\nExperimentsignifikanz.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_055_DE.svg\"\nalt=\"Zwei Vergleichsbalken für die erwartete Asimov-Signifikanz und die Klein-Signal-Näherung.\" />\n<figcaption aria-hidden=\"true\">Zwei Vergleichsbalken für die erwartete\nAsimov-Signifikanz und die Klein-Signal-Näherung.<\/figcaption>\n<\/figure>\n<p><em>Konstruiertes Likelihood-Rechenbeispiel, kein experimentelles\nErgebnis.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Welche Näherung ergibt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s<\/mi><mi>/<\/mi><msqrt><mi>b<\/mi><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">s/\\sqrt b<\/annotation><\/semantics><\/math>\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s<\/mi><mo>=<\/mo><mn>10<\/mn><mo>,<\/mo><mi>b<\/mi><mo>=<\/mo><mn>100<\/mn><\/mrow><annotation encoding=\"application/x-tex\">s=10,b=100<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Wie verändert sich die Näherung bei gleichem\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>s<\/mi><annotation encoding=\"application/x-tex\">s<\/annotation><\/semantics><\/math>\nund vierfachem\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>b<\/mi><annotation encoding=\"application/x-tex\">b<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum darf die Asimov-Formel bei unbekannter Hintergrundunsicherheit\nnicht ungeprüft verwendet werden?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mn>1<\/mn><annotation encoding=\"application/x-tex\">1<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Sie halbiert sich.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Der Test muss den Hintergrund mit seinen Störparametern und\nNebenbedingungen berücksichtigen.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Vorausgesetzt sind ein einzelner Kanal, Poisson-Zählstatistik,\nbekannter Untergrund und asymptotische Interpretation.\nLook-elsewhere-Effekte, systematische Fehler, Selektionen und\nMehrfachtests erfordern eigene Behandlungen. Weder die Demonstration\nnoch ihre Abbildung sind experimentelle Signifikanzangaben.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Damit verbindet M36 die Standardmodellbegriffe mit Kollision,\nDetektion und vorsichtiger Dateninterpretation.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://pdg.lbl.gov/2026/\">Particle Data Group – Review of Particle Physics 2026<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachliche Übersicht zu Teilchenphysik und Statistik; keine Übernahme fremder Tabellen oder Grafiken; Fachlicher Bezug zur Lektion: M36-L8 – Zählexperimente, Likelihood und statistische Evidenz · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://home.cern/science/physics/12-steps-idea-discovery/\">CERN – 12 Steps from Idea to Discovery<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Rekonstruktion von Spuren und Jets, simulierte Signale und statistische Kontrollen; Fachlicher Bezug zur Lektion: M36-L8 – Zählexperimente, Likelihood und statistische Evidenz · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>"};
